    """Rank options by past mood of entries mentioning them (offline stand-in for LLM layer)."""
    d=load(path); r={}
    for o in options:
        m=[e["mood"] for e in d if o.lower() in e["text"].lower()]
        r[o]=round(sum(m)/len(m),2) if m else 0.0
    return sorted(r.items(),key=lambda x:-x[1])

