"""session-to-notes: paste tutoring notes (lines 'Student: note'), get per-student summary + follow-ups."""
import sys,collections
KEY=("homework","practice","review","next","bring","finish","study")
def parse(text):
    d=collections.OrderedDict()
    for l in text.splitlines():
        if ":" in l:
            s,n=l.split(":",1); d.setdefault(s.strip(),[]).append(n.strip())
    return d
def summarize(text):
    out=[]
    for s,ns in parse(text).items():
        fu=[n for n in ns if any(k in n.lower() for k in KEY)]
        out.append(f"{s}\n Summary: {'; '.join(ns)}\n Follow-ups: {'; '.join(fu) or 'none'}\n Parent msg: Hi! Today {s} worked on: {ns[0]}. Next: {fu[0] if fu else 'continue practice'}.")
    return "\n\n".join(out)
if __name__=="__main__": print(summarize(sys.stdin.read()))
